# -*- coding: utf-8 -*-
"""깊은 카드: 도브스 활자(keep-doves) · 중심 방식 = 따라 쓰기 · 5단계: 아이와 함께 끝까지 보기
기준서 1판(보탬 11) · 틀 deep3-4 · 키트 3판 보탬 · 2026-11-18 · 28번 묶음 다섯째 카드
두 질문(기준서 ‘만들기 전 두 질문’):
  1. 그 자리에 있고 싶은 한 순간: 1916년 8월 31일 저녁, 해머스미스 다리 위에서 코브든-샌더슨이 짜 놓은 활자 세 쪽을
     처음 템스강에 던지던 때(그날 한밤중의 일기 · 알렉산더 S. 로슨 아카이브, 런던 박물관). → 장면 3(한가운데 장면, 밤)
  2. 손으로 하는 한 가지는 이야기 속 무엇에서 나오나: 강에 던져진 것이 바로 ‘글자’예요. 그 활자로 찍은 『도브스 성경』 창세기 첫 쪽의
     붉은 ‘IN’(존스턴이 손으로 만든 첫 글자)을 펜글씨 차례대로 한 획씩 따라 써요(획 차례: 스크리블러스의 로마 대문자 쓰는 차례).
  끝맺는 꼴: 기록 한 마디 — 1911년 그가 일기에 적은 유언 같은 글 “강물이 밀물과 썰물로 그 위를 지나가기를”. 나의 자리 물음은
  한가운데 장면의 두 낱말(일기의 ‘없앤다’와 ‘물려준다’)에서 물어요.
카드 크기: 큰 카드(장면 4개). 따라 쓰는 ‘IN’은 이 안내서가 그린 단순한 판이에요(원본 글자를 베끼지 않고 곧은 네 획으로).
앞 카드 keep-ege(흩어진 조각 모으기)·뒤 카드 keep-najeeb(지도 위 길)와 방식이 겹치지 않아요.
그림 원본(src)은 deep_src/keep-doves/ (저장소 밖). 받는 법: commons_get.py
재벌(2026-11-22 · 창 29): 열쇠 물음 셋(qs) · 뒷이야기 세 꾸러미 스무 장(qx) · 후보(qcand). ‘알고 보면’ 칸은 뒷이야기로 옮기고 덜어 냄(링크는 ‘집에서 보기’로).
  본 카드는 악마의 대변인이 길을 잃은 곳에 길잡이 한 줄과 쉬운 말만 넣었어요(status ‘더 깊이(재벌)’ 줄)."""
S = 'keep-doves/'
NKRV = 'https://bible.bskorea.or.kr/bible/NKRV/'
def bl(code, label):   # 성경: 풀어 쓰고 개역개정 링크. 예: bl('LUK.2', '누가복음 2장 7절')
    return f'<a href="{NKRV}{code}" target="_blank" rel="noopener">{label}</a>'

